arguments.cmd:
cat > /app/output/index.html <<'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@700;800;900&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --forest: #2d6a4f;
      --forest-deep: #1f513c;
      --leaf: #52b788;
      --mint: #d8f3dc;
      --cream: #fefae0;
      --cream-soft: #fffdf0;
      --orange: #f4a261;
      --terracotta: #de7d55;
      --yellow: #ffd166;
      --ink: #1e3028;
      --muted: #66766d;
      --white: #ffffff;
      --shadow: 0 20px 55px rgba(45, 106, 79, 0.16);
      --soft-shadow: 0 14px 34px rgba(45, 106, 79, 0.11);
      --radius-lg: 32px;
      --radius-md: 22px;
      --radius-sm: 16px;
    }

    * { box-sizing: border-box; }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      color: var(--ink);
      background:
        radial-gradient(circle at 8% 4%, rgba(255, 209, 102, 0.34), transparent 26rem),
        radial-gradient(circle at 92% 8%, rgba(82, 183, 136, 0.2), transparent 24rem),
        linear-gradient(180deg, var(--cream) 0%, #fffaf0 46%, #f8f7e8 100%);
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.6;
      overflow-x: hidden;
    }

    img {
      display: block;
      width: 100%;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    .container {
      width: min(1160px, calc(100% - 36px));
      margin: 0 auto;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      margin: 0 0 12px;
      padding: 8px 13px;
      border: 1px solid rgba(45, 106, 79, 0.14);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.72);
      color: var(--forest);
      font-size: 0.84rem;
      font-weight: 800;
      letter-spacing: 0.02em;
      box-shadow: 0 8px 20px rgba(45, 106, 79, 0.08);
    }

    h1, h2, h3 {
      font-family: Nunito, Inter, sans-serif;
      line-height: 1.02;
      margin: 0;
      letter-spacing: -0.04em;
    }

    h1 {
      max-width: 760px;
      font-size: clamp(3rem, 8vw, 6.8rem);
      color: var(--forest-deep);
    }

    h2 {
      color: var(--forest-deep);
      font-size: clamp(2.1rem, 4vw, 4rem);
    }

    h3 {
      color: var(--forest-deep);
      font-size: 1.35rem;
    }

    .section-intro {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 30px;
    }

    .section-intro p {
      max-width: 570px;
      margin: 12px 0 0;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 20;
      padding: 16px 0;
      background: rgba(254, 250, 224, 0.78);
      backdrop-filter: blur(18px);
      border-bottom: 1px solid rgba(45, 106, 79, 0.09);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      font-family: Nunito, Inter, sans-serif;
      font-size: 1.35rem;
      font-weight: 900;
      color: var(--forest-deep);
      white-space: nowrap;
    }

    .brand-mark {
      display: grid;
      place-items: center;
      width: 42px;
      height: 42px;
      border-radius: 15px;
      background: var(--forest);
      color: var(--cream);
      box-shadow: 0 10px 20px rgba(45, 106, 79, 0.22);
    }

    .nav {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .nav a {
      padding: 10px 14px;
      border-radius: 999px;
      color: var(--forest-deep);
      font-weight: 800;
      font-size: 0.94rem;
      transition: background 180ms ease, color 180ms ease;
    }

    .nav a:hover {
      background: rgba(45, 106, 79, 0.1);
      color: var(--forest);
    }

    .header-cta,
    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 9px;
      border: 0;
      border-radius: 999px;
      background: var(--forest);
      color: var(--white);
      padding: 13px 20px;
      font: 800 0.96rem/1 Inter, sans-serif;
      cursor: pointer;
      box-shadow: 0 14px 30px rgba(45, 106, 79, 0.22);
      transition: transform 180ms ease, box-shadow 180ms ease, background 180ms ease;
    }

    .button:hover,
    .header-cta:hover {
      transform: translateY(-2px);
      background: var(--forest-deep);
      box-shadow: 0 18px 34px rgba(45, 106, 79, 0.27);
    }

    .button.secondary {
      background: var(--white);
      color: var(--forest);
      border: 1px solid rgba(45, 106, 79, 0.14);
      box-shadow: 0 12px 24px rgba(45, 106, 79, 0.1);
    }

    .hero {
      padding: 66px 0 76px;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: minmax(0, 1.05fr) minmax(340px, 0.75fr);
      gap: 44px;
      align-items: center;
    }

    .hero p {
      max-width: 670px;
      margin: 24px 0 0;
      color: #51635a;
      font-size: clamp(1.08rem, 2vw, 1.32rem);
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 14px;
      margin-top: 34px;
    }

    .hero-card {
      position: relative;
      min-height: 520px;
      border-radius: 42px;
      overflow: hidden;
      background:
        linear-gradient(145deg, rgba(45, 106, 79, 0.02), rgba(244, 162, 97, 0.1)),
        var(--white);
      box-shadow: var(--shadow);
      border: 1px solid rgba(45, 106, 79, 0.08);
    }

    .hero-photo {
      height: 100%;
      min-height: 520px;
      object-fit: cover;
      filter: saturate(1.08) contrast(0.96);
    }

    .hero-card::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, transparent 38%, rgba(31, 81, 60, 0.68));
      pointer-events: none;
    }

    .floating-card {
      position: absolute;
      left: 24px;
      right: 24px;
      bottom: 24px;
      z-index: 1;
      padding: 20px;
      border-radius: 24px;
      background: rgba(255, 253, 240, 0.92);
      backdrop-filter: blur(16px);
      box-shadow: 0 16px 42px rgba(31, 81, 60, 0.22);
    }

    .floating-card strong {
      display: block;
      margin-bottom: 4px;
      color: var(--forest-deep);
      font-family: Nunito, Inter, sans-serif;
      font-size: 1.25rem;
      font-weight: 900;
    }

    .floating-card span {
      color: #51635a;
      font-weight: 600;
    }

    .produce-badge {
      position: absolute;
      top: 22px;
      right: 22px;
      z-index: 1;
      display: grid;
      place-items: center;
      width: 102px;
      height: 102px;
      border-radius: 50%;
      background: var(--yellow);
      color: #6b4b00;
      font-family: Nunito, Inter, sans-serif;
      font-weight: 900;
      text-align: center;
      line-height: 1.05;
      transform: rotate(7deg);
      box-shadow: 0 18px 34px rgba(75, 62, 19, 0.18);
    }

    section {
      padding: 74px 0;
    }

    .featured-shell {
      padding: 34px;
      border-radius: 38px;
      background: rgba(255, 255, 255, 0.62);
      border: 1px solid rgba(45, 106, 79, 0.08);
      box-shadow: 0 28px 70px rgba(45, 106, 79, 0.1);
      overflow: hidden;
    }

    .carousel-controls {
      display: flex;
      gap: 10px;
      flex-shrink: 0;
    }

    .arrow-button {
      display: grid;
      place-items: center;
      width: 48px;
      height: 48px;
      border: 1px solid rgba(45, 106, 79, 0.16);
      border-radius: 50%;
      background: var(--white);
      color: var(--forest);
      font-size: 1.4rem;
      cursor: pointer;
      transition: transform 170ms ease, background 170ms ease, color 170ms ease;
    }

    .arrow-button:hover {
      transform: scale(1.06);
      background: var(--forest);
      color: var(--white);
    }

    .carousel-track {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(245px, 28%);
      gap: 18px;
      overflow-x: auto;
      padding: 8px 4px 18px;
      scroll-behavior: smooth;
      scroll-snap-type: x mandatory;
      scrollbar-width: none;
    }

    .carousel-track::-webkit-scrollbar { display: none; }

    .product-card {
      scroll-snap-align: start;
      display: flex;
      flex-direction: column;
      overflow: hidden;
      min-height: 390px;
      border-radius: 28px;
      background: var(--white);
      border: 1px solid rgba(45, 106, 79, 0.08);
      box-shadow: var(--soft-shadow);
      transition: transform 180ms ease, box-shadow 180ms ease;
    }

    .product-card:hover {
      transform: translateY(-5px);
      box-shadow: 0 20px 42px rgba(45, 106, 79, 0.16);
    }

    .product-card img {
      height: 205px;
      object-fit: cover;
    }

    .product-body {
      display: flex;
      flex: 1;
      flex-direction: column;
      padding: 20px;
    }

    .product-body p {
      margin: 9px 0 18px;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .price-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      margin-top: auto;
    }

    .price {
      color: var(--forest);
      font-family: Nunito, Inter, sans-serif;
      font-size: 1.7rem;
      font-weight: 900;
      letter-spacing: -0.03em;
    }

    .tiny-pill {
      border-radius: 999px;
      background: var(--mint);
      color: var(--forest-deep);
      padding: 7px 10px;
      font-size: 0.78rem;
      font-weight: 800;
    }

    .seasonal {
      background: linear-gradient(135deg, rgba(244, 162, 97, 0.2), rgba(255, 209, 102, 0.18), rgba(216, 243, 220, 0.58));
      border-block: 1px solid rgba(45, 106, 79, 0.08);
    }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 18px;
    }

    .season-card {
      padding: 22px;
      min-height: 250px;
      border-radius: 28px;
      background: rgba(255, 255, 255, 0.75);
      border: 1px solid rgba(45, 106, 79, 0.08);
      box-shadow: var(--soft-shadow);
    }

    .season-card img {
      height: 118px;
      margin-bottom: 18px;
      border-radius: 22px;
      object-fit: cover;
    }

    .season-card p {
      color: var(--muted);
      margin: 8px 0 16px;
      font-size: 0.94rem;
    }

    .categories-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 16px;
    }

    .category-card {
      position: relative;
      min-height: 320px;
      border-radius: 30px;
      overflow: hidden;
      color: var(--white);
      box-shadow: var(--soft-shadow);
      transform: translateZ(0);
      transition: transform 220ms ease, box-shadow 220ms ease;
    }

    .category-card:hover,
    .category-card:focus-within {
      transform: scale(1.035);
      box-shadow: 0 22px 45px rgba(45, 106, 79, 0.2);
    }

    .category-card img {
      height: 100%;
      min-height: 320px;
      object-fit: cover;
      transition: transform 320ms ease;
    }

    .category-card:hover img { transform: scale(1.08); }

    .category-card::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, rgba(31, 81, 60, 0.03), rgba(31, 81, 60, 0.84));
    }

    .category-overlay {
      position: absolute;
      inset: auto 16px 16px;
      z-index: 1;
      padding: 18px;
      border-radius: 22px;
      background: rgba(31, 81, 60, 0.34);
      backdrop-filter: blur(8px);
      transform: translateY(12px);
      transition: transform 220ms ease, background 220ms ease;
    }

    .category-card:hover .category-overlay {
      transform: translateY(0);
      background: rgba(31, 81, 60, 0.56);
    }

    .category-overlay h3 {
      color: var(--white);
      font-size: 1.35rem;
    }

    .category-overlay p {
      margin: 8px 0 0;
      color: rgba(255, 255, 255, 0.86);
      font-size: 0.92rem;
    }

    .stats-banner {
      position: relative;
      overflow: hidden;
      padding: 44px;
      border-radius: 38px;
      background:
        radial-gradient(circle at 5% 10%, rgba(255, 209, 102, 0.55), transparent 18rem),
        linear-gradient(135deg, var(--forest), var(--forest-deep));
      color: var(--white);
      box-shadow: var(--shadow);
    }

    .stats-banner::after {
      content: "✦";
      position: absolute;
      right: 34px;
      top: 14px;
      color: rgba(255, 255, 255, 0.18);
      font-size: 8rem;
      line-height: 1;
    }

    .stats-grid {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }

    .stat strong {
      display: block;
      color: var(--yellow);
      font-family: Nunito, Inter, sans-serif;
      font-size: clamp(2.2rem, 4vw, 3.8rem);
      line-height: 0.95;
      letter-spacing: -0.05em;
    }

    .stat span {
      display: block;
      margin-top: 9px;
      font-weight: 900;
      font-size: 1.02rem;
    }

    .stat p {
      margin: 7px 0 0;
      color: rgba(255, 255, 255, 0.78);
      font-size: 0.9rem;
    }

    .locator-newsletter {
      display: grid;
      grid-template-columns: minmax(0, 1.25fr) minmax(320px, 0.75fr);
      gap: 24px;
      align-items: stretch;
    }

    .panel {
      padding: 34px;
      border-radius: 34px;
      background: rgba(255, 255, 255, 0.76);
      border: 1px solid rgba(45, 106, 79, 0.08);
      box-shadow: var(--soft-shadow);
    }

    .panel p {
      color: var(--muted);
      margin: 12px 0 24px;
    }

    .input-row {
      display: flex;
      gap: 10px;
      align-items: center;
    }

    input {
      width: 100%;
      min-height: 52px;
      border: 1px solid rgba(45, 106, 79, 0.16);
      border-radius: 999px;
      background: var(--cream-soft);
      color: var(--ink);
      padding: 0 18px;
      font: 700 0.97rem/1 Inter, sans-serif;
      outline: none;
      transition: border 160ms ease, box-shadow 160ms ease;
    }

    input:focus {
      border-color: var(--leaf);
      box-shadow: 0 0 0 4px rgba(82, 183, 136, 0.18);
    }

    .store-results {
      display: none;
      grid-template-columns: repeat(3, 1fr);
      gap: 14px;
      margin-top: 22px;
    }

    .store-results.visible {
      display: grid;
      animation: rise 260ms ease both;
    }

    @keyframes rise {
      from { opacity: 0; transform: translateY(10px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .store-card {
      padding: 18px;
      border: 1px solid rgba(45, 106, 79, 0.1);
      border-radius: 22px;
      background: var(--cream-soft);
    }

    .store-card h3 {
      font-size: 1.05rem;
      margin-bottom: 9px;
    }

    .store-card p {
      margin: 6px 0;
      color: var(--muted);
      font-size: 0.9rem;
    }

    .distance {
      display: inline-flex;
      margin-top: 10px;
      border-radius: 999px;
      padding: 6px 10px;
      background: rgba(244, 162, 97, 0.18);
      color: #9b4e28;
      font-weight: 900;
      font-size: 0.82rem;
    }

    .newsletter-panel {
      background:
        radial-gradient(circle at top right, rgba(255, 209, 102, 0.38), transparent 16rem),
        var(--forest);
      color: var(--white);
    }

    .newsletter-panel h2 { color: var(--white); }
    .newsletter-panel p { color: rgba(255, 255, 255, 0.78); }
    .newsletter-panel input { background: rgba(255, 255, 255, 0.92); }
    .newsletter-panel .button { background: var(--orange); color: #432714; box-shadow: none; }

    .confirmation {
      display: none;
      margin-top: 16px;
      padding: 12px 14px;
      border-radius: 16px;
      background: rgba(216, 243, 220, 0.18);
      color: var(--white);
      font-weight: 800;
    }

    .confirmation.visible {
      display: block;
      animation: rise 240ms ease both;
    }

    .site-footer {
      padding: 56px 0 32px;
      background: #173b2b;
      color: var(--white);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 1.4fr repeat(4, 1fr);
      gap: 24px;
      margin-bottom: 40px;
    }

    .footer-brand p {
      max-width: 310px;
      color: rgba(255, 255, 255, 0.7);
      margin: 14px 0 0;
    }

    .footer-column h3 {
      margin-bottom: 12px;
      color: var(--yellow);
      font-size: 1.05rem;
    }

    .footer-column a {
      display: block;
      margin: 8px 0;
      color: rgba(255, 255, 255, 0.74);
      font-weight: 600;
      transition: color 160ms ease;
    }

    .footer-column a:hover { color: var(--white); }

    .footer-bottom {
      padding-top: 24px;
      border-top: 1px solid rgba(255, 255, 255, 0.13);
      color: rgba(255, 255, 255, 0.72);
      text-align: center;
      font-weight: 700;
    }

    @media (max-width: 980px) {
      .header-cta { display: none; }
      .hero-grid,
      .locator-newsletter { grid-template-columns: 1fr; }
      .hero-card, .hero-photo { min-height: 420px; }
      .seasonal-grid,
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .categories-grid { grid-template-columns: repeat(2, 1fr); }
      .carousel-track { grid-auto-columns: minmax(250px, 45%); }
      .store-results { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-brand { grid-column: 1 / -1; }
    }

    @media (max-width: 720px) {
      .site-header { position: static; }
      .header-inner { align-items: flex-start; flex-direction: column; }
      .nav {
        width: 100%;
        overflow-x: auto;
        padding-bottom: 4px;
      }
      .nav a { white-space: nowrap; }
      .hero { padding-top: 36px; }
      section { padding: 54px 0; }
      .section-intro { align-items: flex-start; flex-direction: column; }
      .featured-shell,
      .panel,
      .stats-banner { padding: 24px; border-radius: 28px; }
      .carousel-track { grid-auto-columns: minmax(245px, 82%); }
      .seasonal-grid,
      .categories-grid,
      .stats-grid,
      .footer-grid { grid-template-columns: 1fr; }
      .input-row { flex-direction: column; align-items: stretch; }
      .input-row .button { width: 100%; min-height: 52px; }
      .category-card, .category-card img { min-height: 250px; }
    }
  </style>
</head>
<body>
  <header class="site-header">
    <div class="container header-inner">
      <a class="brand" href="#top" aria-label="Fresh Pantry home">
        <span class="brand-mark" aria-hidden="true">FP</span>
        Fresh Pantry
      </a>
      <nav class="nav" aria-label="Primary navigation">
        <a href="#products">Products</a>
        <a href="#stores">Our Stores</a>
        <a href="#recipes">Recipes</a>
        <a href="#about">About Us</a>
      </nav>
      <a class="header-cta" href="#stores">Find a Store</a>
    </div>
  </header>

  <main id="top">
    <section class="hero" id="about">
      <div class="container hero-grid">
        <div>
          <p class="eyebrow">🥬 Neighborhood groceries, joyfully curated</p>
          <h1>Discover Everyday Deliciousness</h1>
          <p>Unique flavors, quality ingredients, and unbeatable prices — all waiting for you at your neighborhood Fresh Pantry.</p>
          <div class="hero-actions">
            <a class="button" href="#stores">Find a Store Near You</a>
            <a class="button secondary" href="#products">Explore This Week's Picks</a>
          </div>
        </div>
        <div class="hero-card" aria-label="Colorful grocery display">
          <img class="hero-photo" src="https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1000&q=80" alt="Sunlit grocery stand filled with fresh produce">
          <div class="produce-badge">New finds weekly</div>
          <div class="floating-card">
            <strong>Quality meets affordability.</strong>
            <span>Every aisle holds a delicious surprise, from pantry staples to hard-to-find treats.</span>
          </div>
        </div>
      </div>
    </section>

    <section id="products" aria-labelledby="featured-title">
      <div class="container featured-shell">
        <div class="section-intro">
          <div>
            <p class="eyebrow">🛒 Staff favorites</p>
            <h2 id="featured-title">Featured Products</h2>
            <p>A scrollable aisle of cheerful discoveries, craveable staples, and small prices worth smiling about.</p>
          </div>
          <div class="carousel-controls" aria-label="Featured product carousel controls">
            <button class="arrow-button" type="button" id="carouselPrev" aria-label="Previous products">‹</button>
            <button class="arrow-button" type="button" id="carouselNext" aria-label="Next products">›</button>
          </div>
        </div>
        <div class="carousel-track" id="productCarousel" tabindex="0" aria-label="Featured products carousel">
          <article class="product-card">
            <img src="https://images.unsplash.com/photo-1517093157656-b9eccef91cb1?auto=format&fit=crop&w=700&q=80" alt="Jar of granola with oats and nuts">
            <div class="product-body"><h3>Organic Maple Granola</h3><p>Crunchy clusters with real maple syrup and toasted oats</p><div class="price-row"><span class="price">$3.99</span><span class="tiny-pill">Breakfast</span></div></div>
          </article>
          <article class="product-card">
