  <script>
    const carousel = document.getElementById('productCarousel');
    const previousButton = document.getElementById('carouselPrev');
    const nextButton = document.getElementById('carouselNext');

    function slideProducts(direction) {
      const card = carousel.querySelector('.product-card');
      const gap = 18;
      const distance = card ? card.getBoundingClientRect().width + gap : 320;
      carousel.scrollBy({ left: direction * distance, behavior: 'smooth' });
    }

    previousButton.addEventListener('click', () => slideProducts(-1));
    nextButton.addEventListener('click', () => slideProducts(1));

    document.getElementById('storeForm').addEventListener('submit', (event) => {
      event.preventDefault();
      const results = document.getElementById('storeResults');
      results.classList.add('visible');
      results.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    });

    document.getElementById('newsletterForm').addEventListener('submit', (event) => {
      event.preventDefault();
      const confirmation = document.getElementById('newsletterConfirmation');
      confirmation.classList.add('visible');
      event.currentTarget.reset();
    });
  </script>
