      padding: 22px;
      min-height: 250px;
      border-radius: 28px;
      background: rgba(255, 255, 255, 0.75);
      border: 1px solid rgba(45, 106, 79, 0.08);
      box-shadow: var(--soft-shadow);
    }

    .season-card img {
      height: 118px;
      margin-bottom: 18px;
      border-radius: 22px;
      object-fit: cover;
    }

    .season-card p {
      color: var(--muted);
      margin: 8px 0 16px;
      font-size: 0.94rem;
    }

    .categories-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 16px;
    }

    .category-card {
      position: relative;
      min-height: 320px;
      border-radius: 30px;
      overflow: hidden;
      color: var(--white);
      box-shadow: var(--soft-shadow);
      transform: translateZ(0);
      transition: transform 220ms ease, box-shadow 220ms ease;
    }

    .category-card:hover,
    .category-card:focus-within {
      transform: scale(1.035);
      box-shadow: 0 22px 45px rgba(45, 106, 79, 0.2);
    }

    .category-card img {
      height: 100%;
      min-height: 320px;
      object-fit: cover;
      transition: transform 320ms ease;
    }

    .category-card:hover img { transform: scale(1.08); }

    .category-card::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, rgba(31, 81, 60, 0.03), rgba(31, 81, 60, 0.84));
    }

    .category-overlay {
      position: absolute;
      inset: auto 16px 16px;
      z-index: 1;
      padding: 18px;
      border-radius: 22px;
      background: rgba(31, 81, 60, 0.34);
      backdrop-filter: blur(8px);
      transform: translateY(12px);
      transition: transform 220ms ease, background 220ms ease;
    }

    .category-card:hover .category-overlay {
      transform: translateY(0);
      background: rgba(31, 81, 60, 0.56);
    }

    .category-overlay h3 {
      color: var(--white);
      font-size: 1.35rem;
    }

    .category-overlay p {
      margin: 8px 0 0;
      color: rgba(255, 255, 255, 0.86);
      font-size: 0.92rem;
    }

    .stats-banner {
      position: relative;
      overflow: hidden;
      padding: 44px;
      border-radius: 38px;
      background:
        radial-gradient(circle at 5% 10%, rgba(255, 209, 102, 0.55), transparent 18rem),
        linear-gradient(135deg, var(--forest), var(--forest-deep));
      color: var(--white);
      box-shadow: var(--shadow);
    }

    .stats-banner::after {
      content: "✦";
      position: absolute;
      right: 34px;
      top: 14px;
      color: rgba(255, 255, 255, 0.18);
      font-size: 8rem;
      line-height: 1;
    }

    .stats-grid {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }

    .stat strong {
      display: block;
      color: var(--yellow);
      font-family: Nunito, Inter, sans-serif;
      font-size: clamp(2.2rem, 4vw, 3.8rem);
      line-height: 0.95;
      letter-spacing: -0.05em;
    }

    .stat span {
      display: block;
      margin-top: 9px;
      font-weight: 900;
      font-size: 1.02rem;
    }

    .stat p {
      margin: 7px 0 0;
      color: rgba(255, 255, 255, 0.78);
      font-size: 0.9rem;
    }

    .locator-newsletter {
      display: grid;
      grid-template-columns: minmax(0, 1.25fr) minmax(320px, 0.75fr);
      gap: 24px;
      align-items: stretch;
    }

    .panel {
      padding: 34px;
      border-radius: 34px;
      background: rgba(255, 255, 255, 0.76);
      border: 1px solid rgba(45, 106, 79, 0.08);
      box-shadow: var(--soft-shadow);
    }

    .panel p {
      color: var(--muted);
      margin: 12px 0 24px;
    }

    .input-row {
      display: flex;
      gap: 10px;
      align-items: center;
    }

    input {
      width: 100%;
      min-height: 52px;
      border: 1px solid rgba(45, 106, 79, 0.16);
      border-radius: 999px;
      background: var(--cream-soft);
      color: var(--ink);
      padding: 0 18px;
      font: 700 0.97rem/1 Inter, sans-serif;
      outline: none;
      transition: border 160ms ease, box-shadow 160ms ease;
    }

    input:focus {
      border-color: var(--leaf);
      box-shadow: 0 0 0 4px rgba(82, 183, 136, 0.18);
    }

    .store-results {
      display: none;
      grid-template-columns: repeat(3, 1fr);
      gap: 14px;
      margin-top: 22px;
    }

    .store-results.visible {
      display: grid;
      animation: rise 260ms ease both;
    }

    @keyframes rise {
      from { opacity: 0; transform: translateY(10px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .store-card {
      padding: 18px;
      border: 1px solid rgba(45, 106, 79, 0.1);
      border-radius: 22px;
      background: var(--cream-soft);
    }

    .store-card h3 {
      font-size: 1.05rem;
      margin-bottom: 9px;
    }

    .store-card p {
      margin: 6px 0;
      color: var(--muted);
      font-size: 0.9rem;
    }

    .distance {
      display: inline-flex;
      margin-top: 10px;
      border-radius: 999px;
      padding: 6px 10px;
      background: rgba(244, 162, 97, 0.18);
      color: #9b4e28;
      font-weight: 900;
      font-size: 0.82rem;
    }

    .newsletter-panel {
      background:
        radial-gradient(circle at top right, rgba(255, 209, 102, 0.38), transparent 16rem),
        var(--forest);
      color: var(--white);
    }

    .newsletter-panel h2 { color: var(--white); }
    .newsletter-panel p { color: rgba(255, 255, 255, 0.78); }
    .newsletter-panel input { background: rgba(255, 255, 255, 0.92); }
    .newsletter-panel .button { background: var(--orange); color: #432714; box-shadow: none; }

    .confirmation {
      display: none;
      margin-top: 16px;
      padding: 12px 14px;
      border-radius: 16px;
      background: rgba(216, 243, 220, 0.18);
      color: var(--white);
      font-weight: 800;
    }

    .confirmation.visible {
      display: block;
      animation: rise 240ms ease both;
    }

    .site-footer {
      padding: 56px 0 32px;
      background: #173b2b;
      color: var(--white);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 1.4fr repeat(4, 1fr);
      gap: 24px;
      margin-bottom: 40px;
    }

    .footer-brand p {
      max-width: 310px;
      color: rgba(255, 255, 255, 0.7);
      margin: 14px 0 0;
    }

    .footer-column h3 {
      margin-bottom: 12px;
      color: var(--yellow);
      font-size: 1.05rem;
    }

    .footer-column a {
      display: block;
      margin: 8px 0;
      color: rgba(255, 255, 255, 0.74);
      font-weight: 600;
      transition: color 160ms ease;
    }

    .footer-column a:hover { color: var(--white); }

    .footer-bottom {
      padding-top: 24px;
      border-top: 1px solid rgba(255, 255, 255, 0.13);
      color: rgba(255, 255, 255, 0.72);
      text-align: center;
      font-weight: 700;
    }

    @media (max-width: 980px) {
      .header-cta { display: none; }
      .hero-grid,
      .locator-newsletter { grid-template-columns: 1fr; }
      .hero-card, .hero-photo { min-height: 420px; }
      .seasonal-grid,
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .categories-grid { grid-template-columns: repeat(2, 1fr); }
      .carousel-track { grid-auto-columns: minmax(250px, 45%); }
      .store-results { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-brand { grid-column: 1 / -1; }
    }

    @media (max-width: 720px) {
      .site-header { position: static; }
      .header-inner { align-items: flex-start; flex-direction: column; }
      .nav {
        width: 100%;
        overflow-x: auto;
        padding-bottom: 4px;
      }
      .nav a { white-space: nowrap; }
      .hero { padding-top: 36px; }
      section { padding: 54px 0; }
      .section-intro { align-items: flex-start; flex-direction: column; }
      .featured-shell,
      .panel,
      .stats-banner { padding: 24px; border-radius: 28px; }
      .carousel-track { grid-auto-columns: minmax(245px, 82%); }
      .seasonal-grid,
      .categories-grid,
      .stats-grid,
      .footer-grid { grid-template-columns: 1fr; }
      .input-row { flex-direction: column; align-items: stretch; }
      .input-row .button { width: 100%; min-height: 52px; }
      .category-card, .category-card img { min-height: 250px; }
    }
  </style>
</head>
